func (e *external) Update(ctx context.Context, cr *svcapitypes.Domain) (managed.ExternalUpdate, error) {
	input, err := GenerateUpdateDomainConfigInput(cr)
	if err != nil {
		return managed.ExternalUpdate{}, errors.Wrap(err, "cannot build request")
	}
	if err := e.preUpdate(ctx, cr, input); err != nil {
		return managed.ExternalUpdate{}, errors.Wrap(err, "pre-update failed")
	}
	resp, err := e.client.UpdateDomainConfig(ctx, input)
	return e.postUpdate(ctx, cr, resp, managed.ExternalUpdate{}, awsclient.Wrap(err, errUpdate))
}

func (e *external) Delete(ctx context.Context, cr *svcapitypes.Domain) (managed.ExternalDelete, error) {
	cr.Status.SetConditions(xpv2.Deleting())
	input, err := GenerateDeleteDomainInput(cr)
	if err != nil {
		return managed.ExternalDelete{}, errors.Wrap(err, "cannot build request")
	}
	ignore, err := e.preDelete(ctx, cr, input)
	if err != nil {
		return managed.ExternalDelete{}, errors.Wrap(err, "pre-delete failed")
	}
	if ignore {
		return managed.ExternalDelete{}, nil
	}
	resp, err := e.client.DeleteDomain(ctx, input)
	return e.postDelete(ctx, cr, resp, awsclient.Wrap(cpresource.Ignore(IsNotFound, err), errDelete))
}

func (e *external) Disconnect(_ context.Context) error {
	return nil
}

// An option sets hooks of the external client.
type option func(*external)

func newExternal(kube client.Client, client Client, opts []option) *external {
	e := &external{
		kube:           kube,
		client:         client,
		preObserve:     nopPreObserve,
		postObserve:    nopPostObserve,
		lateInitialize: nopLateInitialize,
		isUpToDate:     isUpToDateUpdatable,
		preCreate:      nopPreCreate,
		postCreate:     nopPostCreate,
		preDelete:      nopPreDelete,
		postDelete:     nopPostDelete,
		preUpdate:      nopPreUpdate,
		postUpdate:     nopPostUpdate,
	}
	for _, f := range opts {
		f(e)
	}
	return e
}

